import {registerSearchRoutes} from './search-routes.js';
import {registerFilterRoutes} from './filter-routes.js';
import {persistActivity,listActivity} from './activity.js';
import {notifyActivity,registerNotificationRoutes} from './notifications.js';
import {registerSubscriptionRoutes} from './subscriptions.js';
import {registerDigestRoutes} from './digests.js';
export function registerRoutes(ctx) {
  const unsubscribe=ctx.bus.subscribe(event=>{
    const activity=persistActivity(ctx,event);
    if(activity)notifyActivity(ctx,event,activity);
  });
  (ctx.cleanups??=[]).push(unsubscribe);
  ctx.app.get('/api/v1/activity',ctx.requireAuth,(req,res)=>res.json(listActivity(ctx,req,req.query)));
  registerSubscriptionRoutes(ctx);
  registerNotificationRoutes(ctx);
  registerDigestRoutes(ctx);
  registerSearchRoutes(ctx);
  registerFilterRoutes(ctx);
}

import {validation,fields,choice,text} from '@crew/shared';
import {getIssue} from '../work/issues.js';
export function subscriptionTarget(ctx,req,type,targetId,permission='insight:read') {
  if (!['issue','project'].includes(type)) throw validation({targetType:'Choose issue or project'});
  const issue = type==='issue'?getIssue(ctx,targetId):null;
  const project = ctx.permissions.assertProject(req,issue?.projectId??targetId,permission);
  return {type,targetId,projectId:project.id,orgId:project.org_id,issue};
}
export function publicSubscription(row) {
  return {userId:row.user_id,orgId:row.org_id,projectId:row.project_id,targetType:row.target_type,
    targetId:row.target_id,manual:Boolean(row.manual),reason:row.reason,createdAt:row.created_at};
}
export function canReadProject(ctx,userId,projectId) {
  try { return ctx.permissions.canProject(userId,projectId,'insight:read'); }
  catch(error) { if(error.code==='NOT_FOUND')return false;throw error; }
}
export function subscribe(ctx,userId,target,reason='watch',manual=false) {
  if(!userId || !canReadProject(ctx,userId,target.projectId))return false;
  const existing=ctx.db.prepare('SELECT * FROM subscriptions WHERE user_id=? AND target_type=? AND target_id=?').get(userId,target.type,target.targetId);
  if(existing?.reason==='muted'&&!manual)return false;
  ctx.db.prepare(`INSERT INTO subscriptions(user_id,org_id,project_id,target_type,target_id,manual,reason,created_at)
    VALUES (?,?,?,?,?,?,?,?) ON CONFLICT(user_id,target_type,target_id) DO UPDATE SET
    manual=MAX(manual,excluded.manual),reason=CASE WHEN excluded.manual=1 THEN 'watch' ELSE subscriptions.reason END`)
    .run(userId,target.orgId,target.projectId,target.type,target.targetId,Number(manual),reason,ctx.now());
  return true;
}
export function automaticSubscriptions(ctx,event) {
  const item=event.after??event.before;
  const issue=event.entityType==='issue'?item:item?.issue;
  const issueId=issue?.id??event.issueId??item?.issueId;
  if(!event.projectId||!issueId)return {issueId:null,mentioned:[]};
  const target={type:'issue',targetId:issueId,orgId:event.orgId,projectId:event.projectId};
  if(issue) {
    subscribe(ctx,issue.createdBy,target,'creator');
    subscribe(ctx,issue.assigneeId,target,'assignee');
  }
  const mentioned=[...new Set([...(event.mentionedUserIds??[]),...(event.after?.mentionedUserIds??[]),...(event.after?.userIds??[])])];
  for(const userId of mentioned)subscribe(ctx,userId,target,'mention');
  return {issueId,mentioned};
}
export function registerSubscriptionRoutes(ctx) {
  const {app,requireAuth,permissions:p}=ctx;
  app.get('/api/v1/subscriptions',requireAuth,(req,res)=>{
    p.assertSelf(req,req.user.id,'insight:read');
    if(req.query.orgId)p.assertOrg(req,req.query.orgId,'org:read');
    const rows=ctx.db.prepare("SELECT * FROM subscriptions WHERE user_id=? AND reason<>'muted' ORDER BY created_at DESC,target_id").all(req.user.id)
      .filter(row=>!req.query.orgId||row.org_id===req.query.orgId)
      .filter(row=>!req.query.projectId||row.project_id===req.query.projectId)
      .filter(row=>canReadProject(ctx,req.user.id,row.project_id))
      .map(row=>({...publicSubscription(row),id:row.target_type+':'+row.target_id}));
    res.json(ctx.paginate(rows,req.query));
  });
  app.post('/api/v1/subscriptions',requireAuth,(req,res)=>{
    p.assertSelf(req,req.user.id,'insight:write');
    fields(req.body,['targetType','targetId']);
    const type=choice(req.body.targetType,'targetType',['issue','project']);
    const targetId=text(req.body.targetId,'targetId',{max:128});
    const target=subscriptionTarget(ctx,req,type,targetId);
    const existing=ctx.db.prepare('SELECT 1 FROM subscriptions WHERE user_id=? AND target_type=? AND target_id=?').get(req.user.id,type,targetId);
    if(existing)ctx.db.prepare("UPDATE subscriptions SET manual=1,reason='watch' WHERE user_id=? AND target_type=? AND target_id=?").run(req.user.id,type,targetId);
    else subscribe(ctx,req.user.id,target,'watch',true);
    const row=ctx.db.prepare('SELECT * FROM subscriptions WHERE user_id=? AND target_type=? AND target_id=?').get(req.user.id,type,targetId);
    res.status(201).json({subscription:publicSubscription(row)});
  });
  app.delete('/api/v1/subscriptions/:targetType/:targetId',requireAuth,(req,res)=>{
    p.assertSelf(req,req.user.id,'insight:write');
    const target=subscriptionTarget(ctx,req,req.params.targetType,req.params.targetId);
    subscribe(ctx,req.user.id,target,'muted',true);
    ctx.db.prepare("UPDATE subscriptions SET manual=0,reason='muted' WHERE user_id=? AND target_type=? AND target_id=?").run(req.user.id,target.type,target.targetId);
    res.json({ok:true});
  });
}

import {useEffect,useRef,useState} from 'preact/hooks';
export function liveUrl({orgId,projectId}={}) {
  const query=new URLSearchParams();
  if(orgId)query.set('orgId',orgId);
  if(projectId)query.set('projectId',projectId);
  return '/api/v1/events'+(query.size?'?'+query:'');
}
export function connectLive({orgId,projectId,onActivity=()=>{},onStatus=()=>{},onReset=()=>{},EventSourceClass=globalThis.EventSource}={}) {
  if(!EventSourceClass){onStatus('unavailable');return ()=>{};}
  let active=true;
  const source=new EventSourceClass(liveUrl({orgId,projectId}),{withCredentials:true});
  onStatus('connecting');
  const parse=callback=>event=>{
    if(!active)return;
    try {callback(JSON.parse(event.data));}
    catch(error){onStatus('invalid update');}
  };
  source.addEventListener('ready',()=>active&&onStatus('live'));
  source.addEventListener('activity',parse(onActivity));
  source.addEventListener('reset',parse(onReset));
  source.addEventListener('error',()=>active&&onStatus(source.readyState===2?'closed':'reconnecting'));
  return ()=>{if(active){active=false;source.close();onStatus('paused');}};
}
export function useLiveUpdates({orgId,projectId,onActivity,enabled=true}={}) {
  const callback=useRef(onActivity);
  callback.current=onActivity;
  const [paused,setPaused]=useState(false);
  const [status,setStatus]=useState('paused');
  const [lastEventAt,setLastEventAt]=useState(null);
  useEffect(()=>{
    if(!enabled||paused){setStatus('paused');return;}
    return connectLive({orgId,projectId,onStatus:setStatus,
      onActivity:event=>{setLastEventAt(event.time);callback.current?.(event);},
      onReset:()=>callback.current?.({action:'refresh'})});
  },[orgId,projectId,enabled,paused]);
  return {status,paused,setPaused,lastEventAt};
}

export function activityTitle(event) {
  const item=event.after??event.before??{};
  return item.key?item.key+' · '+(item.title??''):item.title??item.name??event.entityType;
}
export function activityChanges(event) {
  const before=event.before??{},after=event.after??{};
  const names={title:'Title',description:'Description',body:'Comment',statusName:'Status',priority:'Priority',assigneeId:'Assignee',estimate:'Estimate',dueDate:'Due date',parentId:'Parent',role:'Role',name:'Name',archived:'Archived'};
  return Object.entries(names).filter(([key])=>Object.hasOwn(before,key)||Object.hasOwn(after,key))
    .filter(([key])=>JSON.stringify(before[key])!==JSON.stringify(after[key]))
    .map(([key,label])=>({key,label,before:before[key]??'—',after:after[key]??'—'}));
}
export function notificationPath(notification) {
  const event=notification.activity,item=event.after??event.before??{};
  const issueId=event.entityType==='issue'?event.entityId:item.issueId;
  return issueId?'/issues/'+encodeURIComponent(issueId):notification.projectId?'/projects/'+encodeURIComponent(notification.projectId):'/activity?orgId='+encodeURIComponent(notification.orgId);
}
export function feedParameters(values) {
  return Object.fromEntries(Object.entries(values).filter(([,value])=>value!==undefined&&value!==null&&value!==''));
}

import {useState} from 'preact/hooks';
import {Page,Field,Button,Notice,Empty,Loading,useLoad} from '../../components/ui.jsx';
import {queryString} from '../../api.js';
import {useLiveUpdates} from '../../live.js';
import {activityTitle,activityChanges,feedParameters} from './activity-state.js';
export function LiveControl({live}) {
  return <div className="live-control"><span role="status">Updates: {live.status}</span>
    <Button onClick={()=>live.setPaused(!live.paused)}>{live.paused?'Resume live updates':'Pause live updates'}</Button>
    {live.lastEventAt&&<small>Last update {new Date(live.lastEventAt).toLocaleTimeString()}</small>}</div>;
}
export function ActivityEntry({event}) {
  const item=event.after??event.before??{};
  const issueId=event.entityType==='issue'?event.entityId:item.issueId;
  const changes=activityChanges(event);
  return <article className="activity-entry"><header>
    <strong>{issueId?<a href={'#/issues/'+encodeURIComponent(issueId)}>{activityTitle(event)}</a>:activityTitle(event)}</strong>
    <span>{event.entityType} {event.action.replaceAll('_',' ')}</span>
    <time dateTime={event.time}>{new Date(event.time).toLocaleString()}</time>
  </header>{changes.length>0&&<details><summary>{changes.length} field {changes.length===1?'change':'changes'}</summary>
    <dl>{changes.map(change=><div key={change.key}><dt>{change.label}</dt><dd><del>{String(change.before)}</del> → <span>{String(change.after)}</span></dd></div>)}</dl>
  </details>}</article>;
}
export function ActivityPage({api,query,navigate}) {
  const [draft,setDraft]=useState(()=>({orgId:query.orgId??'',projectId:query.projectId??'',issueId:query.issueId??'',userId:query.userId??'',entityType:query.entityType??'',action:query.action??'',from:query.from??'',to:query.to??''}));
  const [applied,setApplied]=useState(draft);
  const [cursor,setCursor]=useState('');
  const [history,setHistory]=useState([]);
  const load=useLoad(()=>applied.orgId?api.get('/activity?'+queryString({...applied,cursor,limit:25})):Promise.resolve(null),[JSON.stringify(applied),cursor]);
  const live=useLiveUpdates({orgId:applied.orgId,projectId:applied.projectId,enabled:Boolean(applied.orgId),onActivity:()=>load.reload()});
  const organizations=useLoad(()=>api.get('/orgs?limit=200'),[]);
  function submit(event){event.preventDefault();setApplied({...draft});setCursor('');setHistory([]);navigate('/activity?'+queryString(feedParameters(draft)));}
  function next(){setHistory([...history,cursor]);setCursor(load.data.nextCursor);}
  function previous(){setCursor(history.at(-1)??'');setHistory(history.slice(0,-1));}
  return <Page title="Activity"><form className="insight-filters" onSubmit={submit}>
    <Field label="Organization"><select value={draft.orgId} onChange={event=>setDraft({...draft,orgId:event.currentTarget.value})}><option value="">Choose organization</option>{organizations.data?.items.map(org=><option key={org.id} value={org.id}>{org.name}</option>)}</select></Field>
    <Field label="Project ID" value={draft.projectId} onInput={event=>setDraft({...draft,projectId:event.currentTarget.value})}/>
    <Field label="Issue ID" value={draft.issueId} onInput={event=>setDraft({...draft,issueId:event.currentTarget.value})}/>
    <Field label="Actor ID" value={draft.userId} onInput={event=>setDraft({...draft,userId:event.currentTarget.value})}/>
    <Field label="Entity"><select value={draft.entityType} onChange={event=>setDraft({...draft,entityType:event.currentTarget.value})}><option value="">All events</option>{['issue','comment','relation','project','label','sprint','attachment','membership','team'].map(type=><option value={type}>{type}</option>)}</select></Field>
    <Field label="Action" value={draft.action} onInput={event=>setDraft({...draft,action:event.currentTarget.value})}/>
    <Field label="From (UTC)" type="datetime-local" value={draft.from.slice(0,16)} onInput={event=>setDraft({...draft,from:event.currentTarget.value?new Date(event.currentTarget.value+'Z').toISOString():''})}/>
    <Field label="To (UTC)" type="datetime-local" value={draft.to.slice(0,16)} onInput={event=>setDraft({...draft,to:event.currentTarget.value?new Date(event.currentTarget.value+'Z').toISOString():''})}/>
    <Button type="submit">Apply filters</Button>
  </form><Notice error={organizations.error??load.error}/>{applied.orgId?<>
    <LiveControl live={live}/>{load.loading?<Loading/>:load.data?.items.length?load.data.items.map(event=><ActivityEntry key={event.id} event={event}/>):<Empty>No matching activity. Changes appear here as the team works.</Empty>}
    <div className="pagination"><Button disabled={!history.length||load.loading} onClick={previous}>Previous</Button><Button disabled={!load.data?.nextCursor||load.loading} onClick={next}>Next</Button><Button busy={load.loading} onClick={load.reload}>Refresh</Button></div>
  </>:<Empty>Choose an organization to see its accessible activity.</Empty>}</Page>;
}

